function renderFoundry(filter=''){const q=filter.trim().toLowerCase();const list=FOUNDRY.filter(f=>!q||(`${f.name} ${f.summary} ${f.tags.join(' ')}`).toLowerCase().includes(q));$('#foundry-grid').innerHTML=list.map(f=>`<article class="panel"><div class="quest-meta"><span class="badge">${f.id}</span><span class="badge ${f.maturity==='stable'?'good':'warn'}">${f.maturity}</span></div><h3>${escapeHtml(f.name)}</h3><p>${escapeHtml(f.summary)}</p><div class="chip-cloud">${f.tags.map(t=>`<span class="chip">${escapeHtml(t)}</span>`).join('')}</div></article>`).join('')||'<p>No capabilities match.</p>'}
function updateHUD(){const xp=QUESTS.filter(q=>state.completedQuests.includes(q.id)).reduce((a,q)=>a+q.xp,0);$('#hud-xp').textContent=xp+' XP';$('#hud-quests').textContent=`${state.completedQuests.length} / ${QUESTS.length}`;$('#hud-streak').textContent=`${state.streak} day${state.streak===1?'':'s'}`;}
function exportState(){const payload={app:'level-up-learning-k12',schemaVersion:1,exportedAt:new Date().toISOString(),state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='level-up-learning-workspace.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importState(file){try{const payload=JSON.parse(await file.text());if(payload.app!=='level-up-learning-k12'||!payload.state)throw new Error('Not a Level Up Learning export');state={...DEFAULT_STATE,...payload.state,schemaVersion:1};await saveState();applyStateToUI();alert('Workspace imported.')}catch(e){alert('Import failed: '+e.message)}}
function diagnostics(){const gpu=!!navigator.gpu,mem=navigator.deviceMemory||null,cores=navigator.hardwareConcurrency||null,sw='serviceWorker'in navigator,idb='indexedDB'in window,bcOk='BroadcastChannel'in window,fs=('showOpenFilePicker'in window),online=navigator.onLine;let model='Deterministic planner only / remote opt-in';if(gpu&&mem>=16)model='Local model class: ~3B–8B quantized may be practical, benchmark first';else if(gpu&&mem>=8)model='Local model class: ~1B–3B quantized; prefer shorter context';else if(gpu)model='Local model class: sub-1B to ~1B; keep deterministic fallback';diagnosticsReport={time:new Date().toISOString(),online,gpu,deviceMemoryGB:mem,hardwareConcurrency:cores,serviceWorker:sw,indexedDB:idb,broadcastChannel:bcOk,fileSystemAccess:fs,recommendation:model,userAgent:navigator.userAgent};$('#ai-readiness').textContent=model;$('#diagnostic-output').textContent=JSON.stringify(diagnosticsReport,null,2);renderCapabilities()}
function renderCapabilities(){const caps=[['IndexedDB','indexedDB'in window,'Local structured persistence','Fallback: localStorage + JSON export'],['Service Worker','serviceWorker'in navigator,'Offline shell and versioned cache','Fallback: normal web/file mode'],['WebGPU',!!navigator.gpu,'Optional local AI / advanced compute','Fallback: deterministic planner'],['BroadcastChannel','BroadcastChannel'in window,'Same-origin tab synchronization','Fallback: single-tab state'],['Web Share','share'in navigator,'Share links/files on supported devices','Fallback: copy/export'],['Fullscreen','fullscreenEnabled'in document,'Presenter deck mode','Fallback: normal deck'],['Online state',navigator.onLine,'Live resource availability','Offline: cached core where hosted']];$('#capability-grid').innerHTML=caps.map(c=>`<article class="panel"><span class="badge ${c[1]?'good':'warn'}">${c[1]?'available':'fallback'}</span><h3>${c[0]}</h3><p>${c[2]}</p><small class="muted">${c[3]}</small></article>`).join('')}
function initBroadcast(){if(!('BroadcastChannel'in window)){$('#sync-status').textContent='BroadcastChannel unavailable; note remains local.';return}bc=new BroadcastChannel('levelup-staff-design');$('#sync-status').textContent='Same-origin staff note sync ready.';bc.onmessage=e=>{if(e.data?.type==='note'&&e.data.value!==$('#shared-note').value){$('#shared-note').value=e.data.value;state.sharedNote=e.data.value;saveState()}};$('#shared-note').addEventListener('input',()=>{state.sharedNote=$('#shared-note').value;saveState();bc.postMessage({type:'note',value:state.sharedNote})})}
function buildSearchIndex(){const items=[];ROUTES.forEach(r=>{const sec=document.getElementById(r.id);items.push({title:r.label,text:sec?.innerText.slice(0,3000)||'',hash:'#'+r.id})});SLIDES.forEach((s,i)=>items.push({title:'Slide '+(i+1)+': '+s.title,text:s.html.replace(/<[^>]+>/g,' '),hash:'#pitch',slide:i}));FOUNDRY.forEach(f=>items.push({title:f.name,text:f.summary+' '+f.tags.join(' '),hash:'#foundry'}));return items};
let SEARCH=[];
function runSearch(q){q=q.trim().toLowerCase();if(!q){$('#search-results').innerHTML='<p class="muted">Type to search routes, deck slides, and adapted Foundry capabilities.</p>';return}const words=q.split(/\s+/);const res=SEARCH.map(x=>({...x,score:words.reduce((n,w)=>n+(x.title+' '+x.text).toLowerCase().split(w).length-1,0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,25);$('#search-results').innerHTML=res.map(x=>`<a class="search-result" href="${x.hash}" data-search-slide="${x.slide??''}"><strong>${escapeHtml(x.title)}</strong><br><small>${escapeHtml(x.text.replace(/\s+/g,' ').slice(0,180))}…</small></a>`).join('')||'<p>No results.</p>'}
function bind(){window.addEventListener('hashchange',route);window.addEventListener('online',updateOnline);window.addEventListener('offline',updateOnline);$('#drawer-toggle').onclick=()=>{const s=$('#sidebar');s.classList.toggle('open');$('#drawer-toggle').setAttribute('aria-expanded',s.classList.contains('open'))};$('#theme-toggle').onclick=async()=>{state.theme=state.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=state.theme;await saveState()};$('#motion-toggle').onclick=async()=>{state.reducedMotion=!state.reducedMotion;document.documentElement.classList.toggle('reduce-motion',state.reducedMotion);await saveState()};$('#prev-slide').onclick=()=>showSlide(currentSlide-1);$('#next-slide').onclick=()=>showSlide(currentSlide+1);$('#fullscreen-deck').onclick=()=>{document.body.classList.toggle('deck-fullscreen');if(document.body.classList.contains('deck-fullscreen'))document.documentElement.requestFullscreen?.().catch(()=>{});else document.exitFullscreen?.().catch(()=>{})};document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)document.body.classList.remove('deck-fullscreen')});document.addEventListener('keydown',e=>{if(document.body.classList.contains('deck-fullscreen')){if(e.key==='ArrowRight'||e.key==='PageDown')showSlide(currentSlide+1);if(e.key==='ArrowLeft'||e.key==='PageUp')showSlide(currentSlide-1);if(e.key==='Escape')document.body.classList.remove('deck-fullscreen')}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search-dialog').showModal();$('#global-search').focus()}});$('#streak-target').onchange=async e=>{state.streakTarget=Math.max(1,Math.min(30,+e.target.value||7));await saveState();updateReadiness()};$('#add-ready-day').onclick=async()=>{state.streak=Math.min(99,(state.streak||0)+1);await saveState();updateReadiness()};$('#record-support-event').onclick=async()=>{if($('#strict-reset').checked){state.streak=0;$('#streak-message').textContent='Strict-reset demo: streak reset. This policy is not recommended because it can create collective blame.'}else $('#streak-message').textContent='Support event recorded conceptually. Default policy: the schoolwide readiness streak is not reset by an individual incident.';await saveState();updateReadiness()};$('#reset-streak').onclick=async()=>{if(confirm('Reset the demo readiness streak?')){state.streak=0;await saveState();updateReadiness()}};$('#refresh-signs').onclick=async()=>{state.schoolName=$('#school-name').value.trim()||'Your School';state.mysteryPhrase=$('#mystery-phrase').value.trim()||DEFAULT_STATE.mysteryPhrase;state.signTarget=Math.max(1,Math.min(30,+$('#sign-target').value||7));await saveState();renderSigns()};$('#run-planner').onclick=planner;$('#run-diagnostics').onclick=diagnostics;$('#copy-diagnostics').onclick=()=>navigator.clipboard?.writeText($('#diagnostic-output').textContent);$('#foundry-filter').oninput=e=>renderFoundry(e.target.value);$('#search-button').onclick=()=>{$('#search-dialog').showModal();$('#global-search').focus()};$('#global-search').oninput=e=>runSearch(e.target.value);$('#search-results').onclick=e=>{const a=e.target.closest('a');if(a&&a.dataset.searchSlide!==''){showSlide(+a.dataset.searchSlide);$('#search-dialog').close()}};['export-state','export-state-2'].forEach(id=>$('#'+id).onclick=exportState);$('#import-state').onchange=e=>{if(e.target.files[0])importState(e.target.files[0]);e.target.value=''};$('#clear-state').onclick=async()=>{if(confirm('Reset all local Level Up Learning prototype data on this browser?')){state={...DEFAULT_STATE};localStorage.removeItem('levelup-state');localStorage.removeItem('levelup-skip-splash');await dbSet('state',state);applyStateToUI()}};$('#gamification-toggle').onchange=async e=>{state.gamification=e.target.checked;document.body.classList.toggle('no-gamification',!state.gamification);await saveState()};$('#analytics-toggle').onchange=async e=>{state.analytics=e.target.checked;await saveState()};$('#splash-toggle').onchange=async e=>{state.showSplash=e.target.checked;if(e.target.checked)localStorage.removeItem('levelup-skip-splash');await saveState()}}
function updateOnline(){const on=navigator.onLine;$('#online-dot').classList.toggle('online',on);$('#online-label').textContent=on?'Online':'Offline';}
async function registerSW(){const lbl=$('#pwa-label');if(!('serviceWorker'in navigator)){lbl.textContent='Service worker unsupported';return}if(location.protocol==='file:'){lbl.textContent='file:// mode — service worker unavailable; core page still works';return}try{await navigator.serviceWorker.register('./sw.js');lbl.textContent='PWA shell registered / offline-ready after first cache'}catch(e){lbl.textContent='PWA registration failed; normal web mode remains usable'}}
